/* Check static-data cache; if miss → build DALL-E 3 prompt */
const body = $input.first().json.body;
const destination = (body.destination || '台灣').replace(/市$|縣$/, '');
const spots = (body.spots || []).filter(Boolean).slice(0, 8);

// Build a short cache key from destination + spots
const rawKey = destination + '|' + spots.join(',');
const cacheKey = 'clay_' + Buffer.from(rawKey).toString('base64').replace(/[^a-zA-Z0-9]/g, '').substring(0, 28);

const staticData = $getWorkflowStaticData('global');
const cachedUrl = staticData[cacheKey];
const cachedTs  = staticData[cacheKey + '_ts'] || 0;
const TTL_MS = 45 * 60 * 1000; // 45 minutes (DALL-E URLs expire in ~1h)

if (cachedUrl && (Date.now() - cachedTs) < TTL_MS) {
  return [{ json: { image_url: cachedUrl, cached: true, cache_key: cacheKey } }];
}

// Build DALL-E 3 prompt
const spotList = spots.length > 0
  ? spots.slice(0, 6).join(', ')
  : `${destination} famous tourist spots`;

const prompt = [
  '3D clay art style miniature diorama tourist map,',
  `Taiwan travel destination "${destination}",`,
  `featuring these attractions as adorable hand-crafted clay figurines and miniature buildings: ${spotList}.`,
  'Isometric bird-eye view, pastel color palette, soft warm lighting,',
  'ultra-detailed clay and plasticine texture with visible fingerprint marks,',
  'charming kawaii cartoon aesthetic, kid-friendly render,',
  'clean white studio background, no text, no labels, no numbers,',
  'highly detailed miniature scale diorama, vibrant cheerful colors.'
].join(' ');

return [{ json: { image_url: null, cached: false, cache_key: cacheKey, prompt } }];

const item = $input.first().json;
const cacheKey = $('Cache Check').first().json.cache_key;

const imageUrl = item.data?.[0]?.url;
if (!imageUrl) throw new Error('DALL-E 3 did not return an image URL. Response: ' + JSON.stringify(item));

// Store in cache (max 15 entries; evict oldest when full)
const staticData = $getWorkflowStaticData('global');
const keys = Object.keys(staticData).filter(k => k.startsWith('clay_') && !k.endsWith('_ts'));
if (keys.length >= 15) {
  let oldest = keys[0], oldestTs = staticData[keys[0] + '_ts'] || 0;
  keys.forEach(k => { const t = staticData[k + '_ts'] || 0; if (t < oldestTs) { oldest = k; oldestTs = t; } });
  delete staticData[oldest];
  delete staticData[oldest + '_ts'];
}
staticData[cacheKey] = imageUrl;
staticData[cacheKey + '_ts'] = Date.now();

return [{ json: { image_url: imageUrl, cached: false } }];
